{
  "slug": "animated-list",
  "name": "Animated List",
  "subtitle": "Staggered list item entrance for tutorials and presentations",
  "description": [
    "Reveals list items one by one with staggered fade-and-slide animations driven by interpolate() and per-item delay offsets. A ready-made scene for feature lists, step-by-step tutorials, agenda slides, or any content that benefits from sequential item reveals.",
    "List items, stagger delay, slide direction, and styles are all customisable through props. The component is a self-contained Remotion scene that composes cleanly inside any Sequence."
  ],
  "category": "Content Animation",
  "tier": "free",
  "duration": 90,
  "fps": 30,
  "isNew": false,
  "author": "React Video Editor",
  "authorLink": "https://www.reactvideoeditor.com",
  "page": "https://www.reactvideoeditor.com/remotion-templates/animated-list",
  "sourceCode": "/**
 * Free Remotion Template Component
 * ---------------------------------
 * This template is free to use in your projects!
 * Credit appreciated but not required.
 *
 * Created by the team at https://www.reactvideoeditor.com
 *
 * Happy coding and building amazing videos! 🎉
 */

"use client";

import { spring, useCurrentFrame, useVideoConfig } from "remotion";

export default function AnimatedList() {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Sample list items
  const items = [
    { name: "Item One", color: "#3b82f6" },
    { name: "Item Two", color: "#60a5fa" },
    { name: "Item Three", color: "#93c5fd" },
  ];

  return (
    <div
      style={{
        position: "absolute",
        top: "50%",
        left: "50%",
        transform: "translate(-50%, -50%)",
        width: "100%",
        maxWidth: "600px",
        padding: "2rem",
      }}
    >
      {items.map((item, i) => {
        const delay = i * 5;

        // Slide in from left
        const slideX = spring({
          frame: frame - delay,
          fps,
          from: -100,
          to: 0,
          config: {
            damping: 12,
            mass: 0.5,
          },
        });

        // Fade in
        const opacity = spring({
          frame: frame - delay,
          fps,
          from: 0,
          to: 1,
          config: {
            damping: 12,
            mass: 0.5,
          },
        });

        // Scale up
        const scale = spring({
          frame: frame - delay,
          fps,
          from: 0.3,
          to: 1,
          config: {
            damping: 12,
            mass: 0.5,
          },
        });

        return (
          <div
            key={i}
            style={{
              display: "flex",
              alignItems: "center",
              gap: "1rem",
              marginBottom: "1rem",
              transform: `translateX(${slideX}px) scale(${scale})`,
              opacity,
            }}
          >
            <div
              style={{
                width: "80px",
                height: "80px",
                borderRadius: "50%",
                backgroundColor: item.color,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                boxShadow: "0 4px 6px rgba(0, 0, 0, 0.1)",
              }}
            />
            <span
              style={{
                color: "white",
                fontSize: "3.5rem",
                fontWeight: 400,
              }}
            >
              {item.name}
            </span>
          </div>
        );
      })}
    </div>
  );
}
"
}
